import sys

MOD = 998244353
V = 100000

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]

    # Smallest prime factor table.
    spf = list(range(V + 1))
    for p in range(2, int(V ** 0.5) + 1):
        if spf[p] == p:
            for q in range(p * p, V + 1, p):
                if spf[q] == q:
                    spf[q] = p

    # Euler's totient function.
    phi = list(range(V + 1))
    for p in range(2, V + 1):
        if phi[p] == p:
            for q in range(p, V + 1, p):
                phi[q] -= phi[q] // p

    # weighted[d] = sum(2^(i-1)) over prior positions i with d | A_i
    weighted = [0] * (V + 1)
    powers = [1] * n
    for i in range(1, n):
        powers[i] = powers[i - 1] * 2 % MOD

    answer = 0
    output = []
    for idx, x in enumerate(values):
        divisors = [1]
        z = x
        while z > 1:
            p = spf[z]
            exponent = 0
            while z % p == 0:
                z //= p
                exponent += 1
            previous = divisors
            divisors = []
            multiple = 1
            for _ in range(exponent + 1):
                divisors.extend(d * multiple for d in previous)
                multiple *= p

        ending_sum = 0
        for d in divisors:
            ending_sum = (ending_sum + phi[d] * weighted[d]) % MOD

        w = powers[idx]
        for d in divisors:
            weighted[d] = (weighted[d] + w) % MOD

        answer = (2 * answer + ending_sum) % MOD
        output.append(str(answer))

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

