import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]
    limit = max(arr)

    # Smallest prime factor for each integer.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    # Grundy number equals the number of prime factors, counted with multiplicity.
    grundy = [0] * (limit + 1)
    for x in range(2, limit + 1):
        grundy[x] = grundy[x // spf[x]] + 1

    xor_sum = 0
    for x in arr:
        xor_sum ^= grundy[x]
    print("Anna" if xor_sum else "Bruno")

if __name__ == "__main__":
    main()

