from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending_at = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending_at[b].append((a, idx))

        largest = second = 0
        largest_id = -1
        gain = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in ending_at[right]:
                if left >= largest:
                    second = largest
                    largest = left
                    largest_id = idx
                elif left > second:
                    second = left

            total += right - largest
            if largest_id != -1:
                gain[largest_id] += largest - second

        return total + max(gain)

