        return
    it = iter(data)
    n = next(it); m = next(it); q = next(it)
    edges = []
    for _ in range(m):
        a = next(it) - 1; b = next(it) - 1; c = next(it)
        edges.append((a, b, c))
    queries = []
    deleted = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            deleted.add(e)
        else:
            x = next(it) - 1; y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for k, (a, b, c) in enumerate(edges):
        if k not in deleted:
            d[a][b] = d[b][a] = c

    for k in range(n):
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik == inf:
                continue
            di = d[i]
            for j in range(n):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            val = d[query[1]][query[2]]
            answers.append(str(val if val < inf else -1))
        else:
            u, v, w = edges[query[1]]
            if d[u][v] <= w:
                continue
            du = [d[i][u] for i in range(n)]
            dv = [d[i][v] for i in range(n)]
            ru = d[u][:]
            rv = d[v][:]
            for i in range(n):
                di = d[i]
                x1 = du[i] + w
                x2 = dv[i] + w
                for j in range(i, n):
                    val = min(di[j], x1 + rv[j], x2 + ru[j])
                    di[j] = val
                    d[j][i] = val

    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
