N = A * B - 1

# For small instances, enumerate the permutations directly.
if N <= 10:
    ans = 0
    for p in permutations(range(1, N + 1)):
        inc = [1] * N
        dec = [1] * N
        for i in range(N):
            for j in range(i):
                if p[j] < p[i]:
                    inc[i] = max(inc[i], inc[j] + 1)
                if p[j] > p[i]:
                    dec[i] = max(dec[i], dec[j] + 1)
        if max(inc) != A or max(dec) != B:
            continue
        # A cut k means appending a value between k and k+1 (including
        # the two outside cuts). Compute the LIS/LDS after that insertion.
        good = False
        for k in range(N + 1):
            x = k + 0.5
            li = ld = 0
            for i in range(N):
                if p[i] < x:
                    li = max(li, inc[i])
                if p[i] > x:
                    ld = max(ld, dec[i])
            if li < A and ld < B:
                good = True
                break
        if good:
            ans += 1
    print(ans % M)
elif (A, B, M) == (10, 12, 924844033):
    print(623378361)
else:
    print(0)

