import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    values = data[2:]
    processes = [tuple(values[i:i + 4]) for i in range(0, len(values), 4)]

    def feasible(target):
        total_cost = 0
        for a, p, b, q in processes:
            g = math.gcd(a, b)
            if p * (b // g) <= q * (a // g):
                # In an optimum, fewer than a/g units of T are needed:
                # replace any such block by b/g units of S.
                best = 10**30
                for y in range(a // g):
                    x = max(0, (target - y * b + a - 1) // a)
                    best = min(best, x * p + y * q)
            else:
                # Symmetrically, fewer than b/g units of S are needed.
                best = 10**30
                for x in range(b // g):
                    y = max(0, (target - x * a + b - 1) // b)
                    best = min(best, x * p + y * q)
            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

