import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    grid = data[1:]

    # Incoming and outgoing neighbors grouped by edge label.
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for i, row in enumerate(grid):
        for j, ch in enumerate(row):
            if ch != 45:  # '-'
                c = ch - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    q = deque()

    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))

    for i in range(n):
        for j in range(n):
            if grid[i][j] != 45 and dist[i][j] > 1:
                dist[i][j] = 1
                q.append((i, j))

    while q:
        u, v = q.popleft()
        d = dist[u][v]

        # Distances 0 and 1 cannot be improved.
        if d <= 1:
            continue

        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            for a in left:
                row = dist[a]
                nd = d + 2
                for b in right:
                    if row[b] > nd:
                        row[b] = nd
                        q.append((a, b))

    out = []
    for row in dist:
        out.append(" ".join(str(x if x < inf else -1) for x in row))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
