N = int(input())
answer = None

# Since N = (x-y)(x^2 + xy + y^2) and x-y=d, we have N > d^3.
for d in range(1, 1_000_001):
    if d * d * d > N:
        break
    if N % d:
        continue

    # N/d = 3y^2 + 3dy + d^2
    discriminant = 12 * (N // d) - 3 * d * d
    if discriminant < 0:
        continue
    root = math.isqrt(discriminant)
    if root * root != discriminant:
        continue
    if (root - 3 * d) % 6:
        continue

    y = (root - 3 * d) // 6
    if y > 0:
        answer = (y + d, y)
        break

if answer is None:
    print(-1)
else:
    print(*answer)

