class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # powers[e] is 10**e modulo k.
        powers = [1] * n
        for e in range(1, n):
            powers[e] = powers[e - 1] * 10 % k

        # Each variable digit contributes to a mirrored pair (or the center).
        weights = []
        for i in range(half):
            mirror = n - 1 - i
            if i == mirror:
                weights.append(powers[i])
            else:
                weights.append((powers[i] + powers[mirror]) % k)

        # dp[i][r]: digits i..half-1 can contribute residue r.
        dp = [bytearray(k) for _ in range(half + 1)]
        dp[half][0] = 1
        for i in range(half - 1, -1, -1):
            w = weights[i]
            following = dp[i + 1]
            current = dp[i]
            for residue in range(k):
                for digit in range(10):
                    if following[(residue - digit * w) % k]:
                        current[residue] = 1
                        break

        # Greedily fix each digit to the largest value allowing completion.
        result = [0] * n
        used = 0
        for i, w in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-used - digit * w) % k
                if dp[i + 1][needed]:
                    result[i] = result[n - 1 - i] = digit
                    used = (used + digit * w) % k
                    break

        return ''.join(map(str, result))

