class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); nxt=[n]*n; st=[]
  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   nxt[i]=st[-1] if st else n
   st.append(i)
  LOG=n.bit_length(); dest=[[n]*n for _ in range(LOG)]; sm=[[0]*n for _ in range(LOG)]
  for i in range(n):
   dest[0][i]=nxt[i]; sm[0][i]=nums[i]*(nxt[i]-i)
  for j in range(1,LOG):
   for i in range(n):
    mid=dest[j-1][i]; dest[j][i]=dest[j-1][mid] if mid<n else n
    sm[j][i]=sm[j-1][i]+(sm[j-1][mid] if mid<n else 0)
  pref=[0]
  for x in nums: pref.append(pref[-1]+x)
  def cost(l,r):
   cur=l; total=0
   for j in range(LOG-1,-1,-1):
    d=dest[j][cur]
    if d<=r:
     total+=sm[j][cur]; cur=d
   total+=nums[cur]*(r-cur+1)
   return total-(pref[r+1]-pref[l])
  ans=0; l=0
  for r in range(n):
   while cost(l,r)>k: l+=1
   ans+=r-l+1
  return ans

