    sz=[1]*total; heavy=[-1]*total
    for x in reversed(order):
        a=left[x]; b=right[x]
        if a!=-1:
            sz[x]=sz[a]+sz[b]
            heavy[x]=a if sz[a]>=sz[b] else b
    head=[0]*total
