from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            # Prefix function for KMP.
            pi = [0] * len(t)
            j = 0
            for i in range(1, len(t)):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == len(t):
                    found.append(i - len(t) + 1)
                    j = pi[j - 1]
            return found

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        ends_a = [start + len(a) for start in starts_a]

        best = n + 1
        for mid in starts_b:
            # Latest A occurrence ending no later than this B occurrence.
            i = bisect_right(ends_a, mid) - 1
            if i < 0:
                continue
            # Earliest C occurrence starting after this B occurrence.
            j = bisect_left(starts_c, mid + len(b))
            if j == len(starts_c):
                continue
            best = min(best, starts_c[j] + len(c) - starts_a[i])

        return -1 if best == n + 1 else best

