from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder, preserving the increasing child order.
        order = []
        stack = [(0, 0)]
        while stack:
            v, visited = stack.pop()
            if visited:
                order.append(v)
            else:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))

        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i
        text = ''.join(s[v] for v in order)

        # Each subtree occupies one contiguous interval in postorder.
        size = [1] * n
        for v in reversed(order):
            for u in children[v]:
                size[v] += size[u]

        # Manacher radii: d1[i] includes the center; d2[i] is centered
        # between i-1 and i.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            end = pos[v]
            length = size[v]
            start = end - length + 1
            if length & 1:
                answer[v] = d1[(start + end) // 2] >= length // 2 + 1
            else:
                answer[v] = d2[(start + end + 1) // 2] >= length // 2
        return answer

