class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def factor_score(values: List[int]) -> int:
            if not values:
                return 0
            common = 0
            multiple = 1
            for value in values:
                common = gcd(common, value)
                multiple = multiple // gcd(multiple, value) * value
            return common * multiple

        best = factor_score(nums)
        for removed in range(len(nums)):
            remaining = nums[:removed] + nums[removed + 1:]
            best = max(best, factor_score(remaining))
