class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            nxt = [0] * 26
            nxt[0] = counts[25]
            nxt[1] = counts[0] + counts[25]
            for i in range(2, 26):
                nxt[i] = counts[i - 1]
            counts = [value % MOD for value in nxt]

        return sum(counts) % MOD

