from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(new, node, left, right):
            current = tree[node]
            if current is None:
                tree[node] = new
                return

            mid = (left + right) // 2
            if value(new, mid) > value(current, mid):
                tree[node], new = new, current
                current = tree[node]

            if left == right:
                return
            if value(new, left) > value(current, left):
                add(new, node * 2, left, mid)
            elif value(new, right) > value(current, right):
                add(new, node * 2 + 1, mid + 1, right)

        def query(x, node, left, right):
            line = tree[node]
            answer = value(line, x) if line is not None else -10**30
            if left == right:
                return answer
            mid = (left + right) // 2
            if x <= mid:
                return max(answer, query(x, node * 2, left, mid))
            return max(answer, query(x, node * 2 + 1, mid + 1, right))

        # A state at index i contributes dp[i] + nums[i] * (j - i)
        # to a jump ending at j, which is a line in j.
        add((nums[0], 0), 1, 0, n - 1)
        best = 0
        for j in range(1, n):
            best = query(j, 1, 0, n - 1)
            add((nums[j], best - nums[j] * j), 1, 0, n - 1)

        return best

