from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        answer = None

        for outlier in nums:
            remaining = total - outlier
            if remaining % 2 != 0:
                continue
            sum_value = remaining // 2

            # The sum element must occupy an index other than the outlier's.
            if counts[sum_value] - (sum_value == outlier) > 0:
                if answer is None or outlier > answer:
                    answer = outlier

        return answer

