from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s in dp[i] is set iff some subset of processed query values
        # covering i sums to s.
        dp = [1] * n
        done = [x == 0 for x in nums]
        remaining = sum(not x for x in done)
        if remaining == 0:
            return 0

        for k, (left, right, val) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue
                dp[i] |= dp[i] << val
                if (dp[i] >> nums[i]) & 1:
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

