import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        # Sieve primes among all values with at most this many digits.
        is_prime = bytearray(b"\x01") * (high + 1)
        is_prime[0] = 0
        if high >= 1:
            is_prime[1] = 0
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                start = p * p
                is_prime[start:high + 1:p] = b"\x00" * (((high - start) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        # A path's cost includes its starting value and every value reached.
        distances = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances[value]:
                continue
            if value == m:
                return cost

            place = 1
            while place <= high:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt <= high and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, float("inf")):
                            distances[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, float("inf")):
                            distances[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                place *= 10

        return -1

