from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the longest common prefix of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        # nxt[j] stores LCP(nums[i+1:], nums[j:]) for current i.
        nxt = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            cur = [0] * (n + 1)
            first_is_prefix = z[i] >= i
            if first_is_prefix:
                # Every valid second boundary satisfies the first condition.
                answer += n - 1 - i

            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    cur[j] = 1 + nxt[j + 1]
                if not first_is_prefix and cur[j] >= j - i:
                    answer += 1
            nxt = cur

        return answer

