class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        inf = 10**30

        # dp[a][b]: minimum cost through the current pair of mirrored
        # houses, whose left/right colors are a and b.
        dp = [[inf] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, m):
            ndp = [[inf] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue
                    pair_cost = cost[i][a] + cost[n - 1 - i][b]
                    best = min(
                        dp[x][y]
                        for x in range(3)
                        for y in range(3)
                        if x != a and y != b
                    )
                    ndp[a][b] = best + pair_cost
            dp = ndp

        return min(min(row) for row in dp)

