class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        # Keep the three longest zero runs. Excluding the two neighboring
        # runs of a chosen one-run can remove at most two candidates.
        top_zeros = sorted(
            ((length, idx) for idx, (ch, length) in enumerate(runs) if ch == '0'),
            reverse=True
        )[:3]

        best_gain = 0
        for idx in range(1, len(runs) - 1):
            if runs[idx][0] != '1':
                continue
            left_idx, right_idx = idx - 1, idx + 1
            if runs[left_idx][0] != '0' or runs[right_idx][0] != '0':
                continue

            # Converting this one-run to zero merges its adjacent zero-runs;
            # converting that merged block yields gain left + right.
            gain = runs[left_idx][1] + runs[right_idx][1]
            # Alternatively, convert any other zero-run in the second step;
            # this costs the length of the one-run sacrificed first.
            alt = 0
            for length, zero_idx in top_zeros:
                if zero_idx != left_idx and zero_idx != right_idx:
                    alt = length - runs[idx][1]
                    break
            best_gain = max(best_gain, gain, alt)

        return ones + best_gain

