class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        n = len(word)
        total = 0

        for left in range(n):
            seen_vowels = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen_vowels.add(ch)
                else:
                    consonants += 1
                    if consonants > k:
                        break

                if consonants == k and len(seen_vowels) == 5:
                    total += 1

        return total

